//      свёртка «осмотр просрочен» по паре «вид × адресат», вал со сводкой; повтор после несостоявшейся попытки; реквизит суммы.
//   Поменялись по канону: #1/#39/#53/#108/#124 (девять источников), #88 (сорок девять видов соседей).
