// Подключение залога (ЗЦ-10…ЗЦ-13, ЗЦ-18, ЗЦ-20, ADR-0326; канон §5.1), волна 17 макета 30.10.2026:
//   AA #236-248 — тринадцатый источник «Залог», пятнадцать видов pk-zl-* (надзор, работа у залога, без «не требуется»): девять по
