//   Переписаны под модель: #39, #88, #97, #98, #185, #190, #194, #236, #238, #239, #249, #260, #265, #276, #296, #297, #303, #317, #321,
//      #368, #369, #372, #381, #386, #391, #392; числа стенда #314, #316, #393, #405. `pk-zl-survey-overdue` → `pk-zl-survey`.
//      #294 падает на восьми строках оснований видов взыскания — виды волны 32. Снятых нет.
// Правки по ревью волны 30 (06.11.2026): «Кто поручил» у очередей комитета, ОПК, отчётности; пустая должность — администратор;
//   вакансия — у владельца, срок от «вакантно с»; руководитель по просрочке — одна проверка, продление гасит «исполнено»;
//   правопреемник без руководителя — выше по дереву; порог статистики — запись; приказ у порога обязателен.
//   #446-449 новые; переписаны #204, #284, #302, #321, #372, #391, #427, #429, #434; числа #314, #393, #405.
// Блоки, которые правят состояние, начинаются с ZD.seed() — состояние между ними не течёт.
// Отчёт печатается в консоль, макет не правится; выход 1 при любом FAIL.
//   node scripts/inspect/zadaniya-check.mjs
import { readFileSync, existsSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { dirname, resolve } from 'node:path';
import vm from 'node:vm';

const __dir = dirname(fileURLToPath(import.meta.url));
const HTML  = resolve(__dir, '../../mockups/zadaniya/zadaniya.html');
const src   = readFileSync(HTML, 'utf8');

const m = src.match(/<script>([\s\S]*?)<\/script>/);
if (!m) { console.error('<script> не найден в HTML'); process.exit(1); }
const win = {};
const sandbox = { window: win, console, setTimeout: () => {}, clearTimeout: () => {} };
vm.createContext(sandbox);
vm.runInContext(m[1], sandbox, { filename: 'zadaniya.inline.js' });
const ZD = win.ZD;
if (!ZD) { console.error('window.ZD не экспортирован'); process.exit(1); }

const results = [];
const ok = (n, cond, note = '') => results.push({ n, pass: !!cond, note });
ZD.seed();
const TODAY = ZD.state.today;
const throws = fn => { try { fn(); return ''; } catch (e) { return e.message || 'ошибка'; } };
/* опрос по сохранению глотает исключения, чтобы сбой не ломал сохранение; сторож #313: ошибка — только от смоделированного отказа источника */
const savePollSeen = { total: 0, swallowed: [] };
const collectSavePolls = () => {
  savePollSeen.total += ZD.state.savePolls.length;
  ZD.state.savePolls.filter(p => p.answer === 'ошибка' && p.error !== 'источник не ответил').forEach(p => savePollSeen.swallowed.push(`${p.src}: ${p.error}`));
};
const seedState0 = ZD.seed;
ZD.seed = () => { collectSavePolls(); return seedState0(); };
const hlRows = (kind, d) => ZD.highlightsOn(d || ZD.state.today).find(x => x.kind === kind).rows; // подсветка: ответ соседа, заданий не рождает
const noWork = kind => !ZD.state.tasks.some(t => t.originKind === kind) && !ZD.state.povods.some(p => p.kind === kind);

/* ---------- A. Первый прогон самоопроса непустой ---------- */
(() => {
  ZD.seed();
  const before = ZD.state.povods.length;
  const r = ZD.runPoll();
  ok(1, before === 0 && r.complete === true && r.sources.length === 17 &&
       r.sources.every(s => s.answer === 'множество'),
    `прогон ${r.id} на дату ${r.date}: все семнадцать источников (self, orgstruct, statistics, reports, gosresh, programs, apps, docs, assets, analysis, credit, collection, collateral, payments, borrower, restructuring, classification) ответили «множество» (ИЗ-12 п.5)`);
  ok(2, r.sources[0].new === 2 && r.sources[0].matched === 0 && r.sources[0].gone === 0,
    `первый прогон непустой на собственных видах (source[0]=self): 2 новых повода из демо-заданий, заведённых ДО опроса (ИЗ-17 приёмка); ` +
    `третье, ждущее приёмки у Абдразаковой, повода не даёт: руководителя у неё нет (ЭЗ-22)`);
  const keys = ZD.state.povods.filter(p => ZD.SELF_KINDS.includes(p.kind)).map(p => p.key).sort();
  ok(3, keys.join('|') === ['pk-overdue|task:T1|','pk-rejected|task:T7|'].sort().join('|'),
    `ключи тройкой «вид · объект · период» (ИЗ-13 п.9) среди собственных видов ` +
    `(org-поводы того же прогона проверяются отдельно, #33+): ${keys.join(', ')}`);
  const issued = ZD.state.tasks.filter(t => t.originKind && ZD.SELF_KINDS.includes(t.originKind));
  ok(4, issued.length === 2 && issued.every(t => t.ruleId && t.ruleEdition === 1),
    `на каждый новый повод СВОЕГО вида правило в авто-режиме выдало задание с редакцией правила (ИЗ-9 п.7): ` +
    `${issued.map(t=>t.id+':'+t.originKind).join(', ')}`);
})();

/* ---------- B. Идемпотентный повтор ---------- */
(() => {
  ZD.seed();
  ZD.runPoll();
  const totalBefore = ZD.state.tasks.length;
  const r2 = ZD.runPoll();
  ok(5, r2.sources[0].new === 0 && r2.sources[0].matched === 2 && r2.sources[0].gone === 0,
    `повторный прогон той же датой: new=0, matched=2, gone=0 — полная сверка множества идемпотентна (ИЗ-3 п.2)`);
  ok(6, ZD.state.tasks.length === totalBefore,
    `повторный прогон не выдал второе задание поверх открытого — иначе ключ «повод × действие» ` +
    `перестал бы держать ≤1 открытое задание на пару (ИЗ-5 п.5)`);
})();

/* ---------- C. Заморозка при недоступном источнике и разморозка ---------- */
(() => {
  ZD.seed();
  ZD.runPoll();
  const appearedBefore = ZD.state.povods.filter(p => p.status === 'appeared').length;
  const rf = ZD.runPoll({ down: true });
  ok(7, rf.complete === false && rf.sources[0].answer === 'ошибка',
    `прогон с недоступным источником объявлен НЕполным в журнале прогонов, а не тихо пропущен (ИЗ-12 п.7)`);
  const frozen = ZD.state.povods.filter(p => p.status === 'frozen');
  ok(8, frozen.length === appearedBefore &&
       frozen.every(p => p.journal[p.journal.length-1].ev === 'заморожен'),
    `молчание соседа не есть пустота: все ${frozen.length} повода заморожены, не отпали ` +
    `(«состояние не подтверждено», ИЗ-12 п.6), в журнал повода вписано «заморожен»`);
  const rr = ZD.runPoll({ down: false });
  ok(9, rr.complete === true && rr.sources[0].new === 0 && rr.sources[0].gone === 0,
    `следующий успешный прогон воспроизводится: заморозка снимается, ни один повод не потерян и ` +
    `не пересчитан как «новый» (сравнить с A/B — тот же результат при том же входе)`);
  const thawed = ZD.state.povods.filter(p => p.status === 'appeared');
  ok(10, thawed.length === appearedBefore &&
        thawed.every(p => p.journal[p.journal.length-1].ev === 'разморожен'),
    `разморозка — отдельная запись журнала «разморожен», не молчаливый откат статуса`);
})();

/* ---------- D. Три реестра (ИЗ-8), ровно 6 своих видов повода (ИЗ-16 п.10) ---------- */
(() => {
  ZD.seed();
  ok(11, ZD.SELF_KINDS.length === 6 &&
        ZD.SELF_KINDS.join(',') === ['pk-overdue','pk-rejected','pk-await-long','pk-neighbor-silent',
          'pk-addr-missing','pk-ext-pending'].join(',') && ZD.SOURCES[0].highlights.join(',') === 'pk-kind-inactive,pk-returning',
    `шесть собственных видов дают задания (вид разбора отпавшего снят, ЭЗ-20), порядок как в каноне §4: ${ZD.SELF_KINDS.join(' · ')}; «вид не введён» и «повод возвращается» — подсветка реестра (ЗНП-1): за них не спросят`);
  const kindsOk = ZD.SELF_KINDS.every(id => {
    const k = ZD.kindOf(id);
    return k && k.objectType && Array.isArray(k.traits) && k.genus === 'самоопрос' && !('rollup' in k) && 'sensitive' in k;
  });
  const actionsOk = ZD.SELF_KINDS.every(id => ZD.actionOf(ZD.ruleForKind(id).action));
  const rulesOk = ZD.SELF_KINDS.every(id => {
    const r = ZD.ruleForKind(id);
    return r && r.author === (id === 'pk-neighbor-silent' ? 'post-it' : 'post-admin') && !('mode' in r) && !('rollup' in r) && Array.isArray(r.editions) &&
      r.editions.length === 1 && r.editions[0].by === 'выпуск 1' && r.editions[0].values.dueN === r.dueN &&
      !('mode' in r.editions[0].values) && !('rollup' in r.editions[0].values);
  });
  ok(12, kindsOk && actionsOk && rulesOk,
    `три реестра держат разные вещи: вид повода — владелец/объект/признаки/род/чувствительность, действие — формулировку и важность, ` +
    `правило — автора-должность/срок и редакции со значениями (у «Источник не отвечает» «Кто поручил» — руководитель ИТ, ВЗЕ-169); режима и порога свёртки нет ни у вида, ни у правила, ни у редакции (ЗНП-3, ЗНП-8)`);
  const mode = throws(() => ZD.editRule('rule-overdue', { mode: 'ручной' }, { by: 'E4', basis: 'приказ' }));
  const roll = throws(() => ZD.editRule('rule-overdue', { rollup: 5 }, { by: 'E4', basis: 'приказ' }));
  ok(13, /выпуском/.test(mode) && /выпуском/.test(roll) && ZD.state.rules.every(r => !('mode' in r)) && ZD.GENERA.indexOf('вал') === -1,
    `все правила авто и другого нет: редакция с режимом или порогом свёртки отбита («${mode}»), ни одно правило реестра режима не держит (ЗНП-8)`);
})();

/* ---------- E. Журнал append-only, состояние выводится, не хранится полем ---------- */
(() => {
  ZD.seed();
  const t = ZD.state.tasks[0];
  const jLenBefore = t.journal.length;
  ok(14, !('state' in t) && !('status' in t) && t.current.ev === ZD.lastEv(t) && ZD.checkStateField().length === 0,
    `у задания одно поле текущего состояния, и оно равно выводу из журнала (ЗНП-5); отдельного статуса нет, журнал главный`);
  ZD.take(t.id);
  ok(15, t.journal.length === jLenBefore + 1 && t.journal[jLenBefore].ev === 'принято' && t.current.ev === 'принято',
    `переход дописал журнал и той же операцией поле, не переписал прежнюю запись — журнал только растёт`);
  const beforeLast = JSON.stringify(t.journal[0]);
  ok(16, JSON.stringify(t.journal[0]) === beforeLast,
    `более ранняя запись журнала не изменилась переходом — задним числом журнал не переписывается`);
})();

/* ---------- F. Исход выводится перекрёстно, не раньше срока ---------- */
(() => {
  ZD.seed();
  const t = ZD.state.tasks.find(x => ZD.deriveState(x).indexOf('отказано') === -1 && ZD.deriveState(x) !== 'ожидает приёмки');
  ok(17, ZD.outcomeOf(t) === null,
    `у незакрытого задания исхода нет — исход не поле, а вывод только из терминальной записи (ИЗ-6)`);
  const rejected = ZD.state.tasks.find(x => ZD.deriveState(x) === 'отказано');
  ZD.releaseTask(rejected.id, rejected.author, 'решение автора — демо');
  const o = ZD.outcomeOf(rejected);
  ok(18, o && o.outcome === 'снято' && ZD.isTerminal(rejected),
    `«снято» — исход по решению автора, с основанием (после отказа — частный случай: снимать можно из любого нетерминального)`);
})();

/* ---------- G. Свободное поручение без контролёра не бывает (ИЗ-7 п.13): по умолчанию контролёр — автор (ЭЗ-14) ---------- */
(() => {
  ZD.seed();
  const dflt = ZD.createFreeTask({ label:'демо без контролёра', assignee:'E1', author:'E4', dueDate:'2026-09-10' });
  const self = throws(() => ZD.createFreeTask({ label:'сам себя', assignee:'E1', controller:'E1', author:'E4', dueDate:'2026-09-10' }));
  ok(19, dflt.controller === 'E4' && /контролёр/.test(self),
    `свободное поручение без контролёра не заводится: не назван — контролёр автор (ЭЗ-14); исполнитель сам себе контролёром быть не может: «${self}»`);
  const t = ZD.createFreeTask({ label:'демо с контролёром', assignee:'E1', controller:'E4', author:'E4', dueDate:'2026-09-10' });
  ok(20, !!t && t.controller === 'E4',
    `с контролёром свободное поручение заводится штатно`);
})();

/* ---------- H. Ручного режима нет: «назначает пользователь» — свободное поручение, ненужное снимает автор (ЗНП-8) ---------- */
(() => {
  ZD.seed();
  const free = ZD.state.tasks.filter(t => t.kind === 'free');
  ok(21, free.length === 4 && free.every(t => t.controller),
    `«назначает пользователь» — свободное поручение без повода и ключа, с обязательным контролёром (ЗНП-8): ` +
    `${free.length} демо-задания заведены до первого опроса`);
  const mode = throws(() => ZD.editRule('rule-org-head-vacant', { mode: 'ручной' }, { by: 'E4', basis: 'приказ №12' }));
  ZD.runPoll();
  const heads = ZD.state.tasks.filter(t => t.originKind === 'pk-org-head-vacant');
  ok(22, /выпуском/.test(mode) && heads.length === 2 && heads.every(t => t.povodKey && t.addr.by === 'оргструктура') &&
       !ZD.state.tasks.some(t => t.decide || t.rollupKeys) && ZD.taskRows().every(r => r.genus !== 'решить' && r.genus !== 'вал') && ZD.decidePovods === undefined,
    `рода «решить по поводам» нет: правило надзора не переводится в ручной режим, прогон сам выдал два задания адресатам по формуле (ЗНП-8; вакансия, прикрытая и.о., поводом не стала — ВЗЕ-154)`);
  const t3 = heads[1], n = heads.length;
  const noBasis = throws(() => ZD.releaseTask(t3.id, t3.author, ''));
  const stranger = throws(() => ZD.releaseTask(t3.id, 'E3', 'не нужно'));
  ZD.releaseTask(t3.id, t3.author, 'вакансия закрывается конкурсом');
  ZD.runPoll();
  const after = ZD.state.tasks.filter(t => t.originKind === 'pk-org-head-vacant');
  ok(23, /основание/.test(noBasis) && /автор/.test(stranger) && ZD.outcomeOf(t3).outcome === 'снято' && after.length === n &&
       ZD.povodReleased(ZD.povodByKey(t3.povodKey)),
    `ненужное снимает автор кнопкой «Снять» с основанием: тот же результат, что давал ручной режим — ключ не всплыл на следующем прогоне (ЗНП-8)`);
})();

/* ---------- I. Жёсткий стопор рекурсии, один шаг (ИЗ-16 п.11) ---------- */
(() => {
  ZD.seed();
  ZD.runPoll();
  const born = ZD.state.tasks.find(t => t.originKind === 'pk-overdue');
  born.dueDate = '2026-08-01'; // искусственно просрочили задание, рождённое поводом «просрочено»
  const before = ZD.state.povods.length;
  const r2 = ZD.runPoll();
  const recursed = ZD.state.povods.some(p => p.key.indexOf(born.id) !== -1);
  ok(24, !recursed && r2.sources[0].new === 0 && r2.sources[0].matched === 2,
    `просроченное задание, рождённое поводом «просрочено», НЕ породило второй повод «просрочено» ` +
    `на себя — originKind===kindId стопорит рекурсию за один шаг, а не настраиваемой глубиной`);
})();

/* ---------- J. Рубильник вида повода (ИЗ-13 п.12) ---------- */
(() => {
  ZD.seed();
  const err = fn => { try { fn(); return ''; } catch (e) { return e.message; } };
  ZD.runPoll();
  const open = ZD.state.tasks.filter(t => t.originKind === 'pk-org-head-vacant' && !ZD.isTerminal(t));
  const self = err(() => ZD.deactivateKind('pk-rejected', 'E4', 'приказ'));
  const step = err(() => ZD.deactivateKind('doc-sign', 'E4', 'приказ'));
  const hl = err(() => ZD.deactivateKind('lp-expiring', 'E4', 'приказ'));
  const user = err(() => ZD.deactivateKind('pk-org-head-vacant', 'E2', 'приказ'));
  const bare = err(() => ZD.deactivateKind('pk-org-head-vacant', 'E4', ''));
  ZD.deactivateKind('pk-org-head-vacant', 'E4', 'приказ №14 — вакансии ведёт кадровая служба');
  ok(25, /выпуском/.test(self) && /выпуском/.test(step) && /выпуском/.test(hl) && /администратор/.test(user) && /основание/.test(bare) &&
       ZD.kindOf('pk-org-head-vacant').activatedAt === null && open.length === 2 &&
       open.every(t => ZD.outcomeOf(t) && ZD.outcomeOf(t).outcome === 'снято' && /вид выключен/.test(ZD.outcomeOf(t).reason)),
    `рубильник — только у надзора и сигнала и только у администратора заданий с основанием: самоопрос, шаг документа и подсветка выключаются выпуском; ` +
    `выключение надзора закрыло его 3 открытых задания «снято: вид выключен»`);
  ZD.state.today = '2026-09-03';
  ZD.runPoll();
  const ownPovod = ZD.state.povods.some(p => p.kind === 'pk-org-head-vacant' && p.status !== 'gone');
  const metaOff = hlRows('pk-kind-inactive').some(r => r.objectId === 'pk-org-head-vacant');
  const k = ZD.kindOf('pk-stat-neighbor-silent'); k.activatedAt = null; k.createdAt = '2026-08-28'; // пришёл выпуском и не введён
  ZD.runPoll();
  const metaNew = hlRows('pk-kind-inactive').some(r => r.objectId === 'pk-stat-neighbor-silent');
  ok(26, !ownPovod && !metaOff && metaNew && noWork('pk-kind-inactive'),
    `выключенный надзор своих поводов не даёт и «не введён в действие» не считается — выключен с основанием; вид, пришедший ` +
    `выпуском и не введённый дольше срока, виден в подсветке реестра, задания и повода нет (ЗНП-1)`);
  ZD.activateKind('pk-org-head-vacant', 'E4', 'приказ №15');
  ZD.runPoll();
  const revived = ZD.state.povods.some(p => p.kind === 'pk-org-head-vacant' && p.status !== 'gone');
  ok(27, revived && ZD.kindOf('pk-org-head-vacant').switches.map(s => s.ev).join() === 'выключен,введён в действие',
    `надзор включён обратно — поводы вернулись; ввод и выключение лежат в истории вида с основанием — рубильник обратим`);
})();


/* ---------- K. Уведомления: закрытый список из девяти состояний (ИЗ-14 п.1) ---------- */
(() => {
  ZD.seed();
  const CLOSED = ['поручено','принято','срок-близко','срок-истёк','эскалация','возвращено','повод-отпал','закрыто',
    'переадресовано','запрошено-продление','решение-по-продлению'];
  ok(28, ZD.NOTIF_KINDS.length === 11 && ZD.NOTIF_KINDS.join(',') === CLOSED.join(','),
    `одиннадцать видов (ЭЗ-15), ни одного информационного («кредит выдан») — список закрыт буквально (канон §6, ИЗ-21)`);
  ZD.seed();
  const beforeN = ZD.state.notifications.length;
  ZD.runPoll();
  const afterN = ZD.state.notifications.length;
  ok(29, afterN > beforeN && ZD.state.notifications.every(n => CLOSED.includes(n.kind)),
    `самоопрос породил уведомления, и каждое — из закрытого списка (движок бросил бы на восьмом глаголе)`);
})();

/* ---------- L. Сторож чистоты макета, «сегодня» заморожено ---------- */
(() => {
  const noComm = m[1];
  const refs = src.match(/ADR-\d{4}|ИЗ-\d+|ИО-\d+|ЗН-\d+|ЗГ-\d+|ЗКП-\d+|ЗЗ-\d+|ЗА-\d+|ИА-\d+|ЗДБ-\d+|ЗНС-\d+|ЗЦ-\d+|ЗНП-\d+|ЭЗ-\d+|P\d+-R\d+|[Вв]олн[аеыуой][ -]*\d/g) || [];
  ok(30, refs.length === 0,
    `макет чистый: ни ADR-, ни ИЗ-/ИО-/ЗН-/ЗГ-/ЗКП-/ЗЗ-/ЗА-/ИА-номеров, ни истории волн — пояснения живут в ` +
    `ASUBK-zadaniya-logika.md и журнале волн${refs.length?' · найдено: '+[...new Set(refs)].join(', '):''}`);
  const frozen = /today:\s*'2026-09-02'/.test(noComm) &&
                 !/Date\.now\(\)/.test(noComm) && !/new Date\(\s*\)/.test(noComm);
  ok(31, frozen,
    `«сегодня» заморожено константой '2026-09-02' в состоянии, системных часов в движке нет — ` +
    `прогон воспроизводится между запусками смоука`);
  const scriptOpenCount = (src.match(/<script>/g) || []).length;
  const scriptCloseCount = (src.match(/<\/script>/g) || []).length;
  ok(32, scriptOpenCount === 1 && scriptCloseCount === 1,
    `ровно один открывающий и один закрывающий тег script во всём файле, включая шапку и уже вписанный ` +
    `отчёт — наивный извлекатель регэкспом (этот смоук и его аналог для kuratorstvo) иначе режет не с того места`);
})();

