  const rn = ZD.state.rules.find(r => r.addressee.by === 'названный' && typeof r.author === 'string');
  const nm = ZD.resolveAddressee(rn, { kind: rn.kind, named: null, traits: {} }, '2026-09-02');
  const lp = ZD.POSTS.find(p => p.id === 'post-lp');
