  pollOn('2026-12-03');
  const kx = ZD.kindOf('pl-refund-exec'), rx = ZD.ruleForKind('pl-refund-exec'), ka = ZD.kindOf('pl-act-sign'), ra = ZD.ruleForKind('pl-act-sign');
